INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(9031, 'koKR', 'Uciekajcie! Nadchodzą!', 'Uciekajcie! Nadchodzą!', 0),
(9591, 'koKR', 'Jeśli spadnę w otchłań, pociągnę was wszystkich, śmiertelnicy, za sobą!', '', 0),
(9592, 'koKR', '%s uciekają, gdy kontrolująca ich moc kuli słabnie.', '', 0),
(9793, 'koKR', '%s wzdryga się, a jego skóra zaczyna migotać.', '', 0),
(9958, 'koKR', 'Intruzi wdarli się do wylęgarni! Podnieść alarm! Chrońcie jaja za wszelką cenę!', '', 0),
(9961, 'koKR', 'Zapłacicie mi za to, że mnie do tego zmusiliście!', '', 0),
(9962, 'koKR', 'Głupcy! Te jaja są cenniejsze, niż sądzicie!', '', 0),
(9963, 'koKR', 'Nie... nie kolejne! Za to okrucieństwo zapłacicie głowami!', '', 0),
(9967, 'koKR', 'Nikt z waszego rodzaju nie powinien tu przebywać! Zgubiliście tylko samych siebie!', '', 0),
(9968, 'koKR', 'Sprytnie, śmiertelnicy, ale nie tak łatwo odciągnąć mnie od mojego sanktuarium!', '', 0);
